/**
 * verify-firebase-boundary.mjs
 *
 * @version 1
 *
 * GOOGLE_FIREBASE_STANDARDS.yaml, mechanical. Applies only when a package.json
 * declares firebase / firebase-admin; green no-op otherwise.
 *   1. banned files: src/lib/firebase-client.*, src/middleware.ts (proxy.ts is the sanctioned path)
 *   2. ZERO client-side Firebase SDK: no import from "firebase/<anything>" (server uses firebase-admin)
 *   3. no NEXT_PUBLIC_FIREBASE_* vars anywhere (client SDK is banned, so no public firebase config)
 *   4. no NEXT_PUBLIC_ var naming a secret (SECRET|PRIVATE|TOKEN|PASSWORD|SERVICE_ACCOUNT)
 *   5. no email-allowlist authorization (ADMIN_EMAILS / ALLOWED_EMAILS) — permission-slug catalog instead
 *
 * Usage: node verify-firebase-boundary.mjs [<root>]   (default: cwd)
 * Exit: 0 green, 1 red.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";

const GREEN = "\x1b[32m";
const RED = "\x1b[31m";
const RESET = "\x1b[0m";
const NAME = "verify-firebase-boundary";

const SKIP_DIRS = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "coverage", "out", ".archive"]);

function* walk(dir) {
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    if (ent.isDirectory()) {
      if (!SKIP_DIRS.has(ent.name)) yield* walk(path.join(dir, ent.name));
    } else yield path.join(dir, ent.name);
  }
}

const root = path.resolve(process.cwd(), process.argv[2] || ".");
const all = fs.existsSync(root) ? [...walk(root)] : [];

const usesFirebase = all
  .filter((f) => path.basename(f) === "package.json")
  .some((f) => {
    try {
      const p = JSON.parse(fs.readFileSync(f, "utf8"));
      const deps = { ...p.dependencies, ...p.devDependencies };
      return Object.keys(deps || {}).some((d) => d === "firebase" || d === "firebase-admin" || d.startsWith("@firebase/"));
    } catch { return false; }
  });

if (!usesFirebase) {
  process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — no firebase dependency; nothing to verify.\n`);
  process.exit(0);
}

const violations = [];
let scanned = 0;

for (const f of all) {
  const rel = path.relative(root, f);
  if (/src\/lib\/firebase-client\.[a-z]+$/.test(rel)) violations.push({ rel, rule: "banned file — client-side Firebase module (server-only Admin SDK is the sole path)" });
  if (/src\/middleware\.ts$/.test(rel)) violations.push({ rel, rule: "banned file — use src/proxy.ts, not src/middleware.ts" });

  const isCode = /\.(ts|tsx|mts|js|mjs|jsx)$/.test(rel);
  const isEnv = /(^|\/)\.env[^/]*$/.test(rel);
  if (!isCode && !isEnv) continue;
  scanned++;
  const text = fs.readFileSync(f, "utf8");

  if (isCode) {
    for (const m of text.matchAll(/from\s+['"]firebase\/([a-z-]+)['"]/g)) {
      violations.push({ rel, rule: `client Firebase SDK import "firebase/${m[1]}" — ZERO client-side SDK; use firebase-admin server-side` });
    }
  }
  for (const m of text.matchAll(/NEXT_PUBLIC_FIREBASE_[A-Z0-9_]*/g)) {
    violations.push({ rel, rule: `${m[0]} — client SDK is banned, so no public firebase config vars` });
  }
  for (const m of text.matchAll(/NEXT_PUBLIC_[A-Z0-9_]*(SECRET|PRIVATE|TOKEN|PASSWORD|SERVICE_ACCOUNT)[A-Z0-9_]*/g)) {
    violations.push({ rel, rule: `${m[0]} — NEXT_PUBLIC_ must never carry a server-only secret` });
  }
  for (const m of text.matchAll(/\b(ADMIN_EMAILS|ALLOWED_EMAILS)\b/g)) {
    violations.push({ rel, rule: `${m[1]} — email-allowlist authorization is banned; use the permission-slug catalog` });
  }
}

const dedup = [...new Map(violations.map((v) => [v.rel + v.rule, v])).values()];
if (dedup.length === 0) {
  process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — firebase repo; ${scanned} file(s) scanned; boundary clean.\n`);
  process.exit(0);
}
process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${dedup.length} violation(s)\n`);
for (const v of dedup) process.stderr.write(`  [${v.rel}] ${v.rule}\n`);
process.stderr.write(`Per GOOGLE_FIREBASE_STANDARDS.yaml — server-side Admin SDK only; permission-slug authorization.\n`);
process.exit(1);
